/* The tables of M26 · Staff and recruitment. */

export const departments = defineTable(
  'departments',
  { module: 'M26', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    nameUr: text(),
    code: text().notNull(),
    headStaffId: uuid().references((): AnyPgColumn => staff.id),
    parentId: uuid().references((): AnyPgColumn => departments.id),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    uniqueIndex('departments_name_uq').on(t.orgId, t.name).where(live(t)),
    uniqueIndex('departments_code_uq').on(t.orgId, t.code).where(live(t)),
  ],
);

export const designations = defineTable(
  'designations',
  { module: 'M26', scope: 'org' },
  {
    ...baseColumns,
    /** "Senior Teacher", "Accountant" */
    name: text().notNull(),
    nameUr: text(),
    category: enumText(designationCategories).notNull(),
    isTeaching: boolean().notNull().default(false),
    payGrade: integer(),
    isActive: boolean().notNull().default(true),
  },
  (t) => [uniqueIndex('designations_name_uq').on(t.orgId, t.name).where(live(t))],
);

/** The directory record. Readable by every staff member of the organisation, so it holds nothing private. */
export const staff = defineTable(
  'staff',
  { module: 'M26', scope: 'org' },
  {
    ...baseColumns,
    /** from the `employee` sequence */
    employeeNo: text().notNull(),
    fullName: text().notNull(),
    fullNameUr: text(),
    fatherOrHusbandName: text(),
    gender: enumText(genders).notNull(),
    photoFileId: uuid().references((): AnyPgColumn => files.id),
    designationId: uuid()
      .references((): AnyPgColumn => designations.id)
      .notNull(),
    departmentId: uuid().references((): AnyPgColumn => departments.id),
    homeBranchId: uuid()
      .references((): AnyPgColumn => branches.id)
      .notNull(),
    wingId: uuid().references((): AnyPgColumn => wings.id),
    /** not themselves, and no loops */
    reportsToStaffId: uuid().references((): AnyPgColumn => staff.id),
    staffType: enumText(staffStaffTypes).notNull(),
    employmentType: enumText(staffEmploymentTypes).notNull(),
    joinedOn: dateStr().notNull(),
    /** required for `probation` */
    probationEndsOn: dateStr(),
    confirmedOn: dateStr(),
    /** required for `contract` */
    contractEndsOn: dateStr(),
    lastWorkingDay: dateStr(),
    status: enumText(staffStatuses).notNull().default('active'),
    /** normalised */
    workPhone: text(),
    workEmail: text(),
    shiftId: uuid().references((): AnyPgColumn => shifts.id),
    /** falls back to the branch default */
    workScheduleId: uuid().references((): AnyPgColumn => workSchedules.id),
    /** used for timetable and substitute suggestions */
    teachableSubjectIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    /** for teaching staff */
    maxLessonsPerWeek: integer(),
    /** custom fields */
    custom: jsonb().notNull().default({}),
  },
  (t) => [
    check('staff_reports_to_staff_id_not_self', sql`${t.reportsToStaffId} <> ${t.id}`),
    check(
      'staff_probation_ends_on_needed',
      sql`${t.employmentType} <> 'probation' or ${t.probationEndsOn} is not null`,
    ),
    check(
      'staff_contract_ends_on_needed',
      sql`${t.employmentType} <> 'contract' or ${t.contractEndsOn} is not null`,
    ),
    uniqueIndex('staff_employee_no_uq').on(t.orgId, t.employeeNo).where(live(t)),
    index('staff_home_branch_status_idx').on(t.orgId, t.homeBranchId, t.status),
    index('staff_full_name_trgm').using('gin', sql`${t.fullName} gin_trgm_ops`),
    index('staff_employee_no_trgm').using('gin', sql`${t.employeeNo} gin_trgm_ops`),
  ],
);

/** One row per staff member. */
export const staffPrivate = defineTable(
  'staff_private',
  { module: 'M26', scope: 'org', cap: 'hr', capOwner: 'staffId' },
  {
    ...baseColumns,
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    /** 13 digits; unique per organisation among staff not `left` */
    cnic: text().notNull(),
    cnicExpiresOn: dateStr(),
    /** at least 18 years before `joined_on` */
    dateOfBirth: dateStr().notNull(),
    maritalStatus: enumText(staffPrivateMaritalStatuses),
    religion: text(),
    bloodGroup: text(),
    /** normalised */
    personalPhone: text().notNull(),
    personalEmail: text(),
    address: text(),
    city: text(),
    emergencyName: text(),
    emergencyPhone: text(),
    emergencyRelation: text(),
    eobiNo: text(),
    socialSecurityNo: text(),
    /** declared on joining */
    previousIncomeThisTaxYear: paisa().notNull().default(0),
    previousTaxThisTaxYear: paisa().notNull().default(0),
  },
  (t) => [
    nonNegative('staff_private', t.previousIncomeThisTaxYear),
    nonNegative('staff_private', t.previousTaxThisTaxYear),
    uniqueIndex('staff_private_staff_uq').on(t.staffId).where(live(t)),
  ],
);

export const staffBankAccounts = defineTable(
  'staff_bank_accounts',
  { module: 'M26', scope: 'org', cap: 'hr', capOwner: 'staffId' },
  {
    ...baseColumns,
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    bankName: text().notNull(),
    accountTitle: text().notNull(),
    accountNo: text().notNull(),
    /** a valid Pakistani IBAN */
    iban: text(),
    /** one primary per staff member */
    isPrimary: boolean().notNull().default(true),
    status: enumText(staffBankAccountStatuses).notNull().default('active'),
  },
  (t) => [
    uniqueIndex('staff_bank_accounts_primary_uq')
      .on(t.staffId)
      .where(sql`${t.isPrimary} and ${t.deletedAt} is null`),
  ],
);

